const enc = new TextEncoder();
const dec = new TextDecoder();
const MICRO = 1_000_000;
const json = (x) => JSON.stringify(x ?? {});
const micro = (n) => Math.round(Number(n) * MICRO);
const money = (n) => Math.round(Number(n || 0)) / MICRO;
const now = () => new Date().toISOString();
const id = (prefix) => `${prefix}_${crypto.randomUUID().replaceAll('-', '')}`;
const email = (v) => String(v || '').trim().toLowerCase();
const localParts = (date = new Date()) => {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hourCycle:'h23' }).formatToParts(date);
  const o={}; for (const p of f) o[p.type]=p.value; return o;
};
const localDateKey = (date = new Date()) => { const p=localParts(date); return `${p.year}-${p.month}-${p.day}`; };
const localMinutes = (date = new Date()) => { const p=localParts(date); return Number(p.hour)*60+Number(p.minute); };
function addLocalDays(key, days) { const [y,m,d]=key.split('-').map(Number); const dt=new Date(Date.UTC(y,m-1,d+days,12)); return new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(dt); }
function localDaysBetween(a,b){ const ka=localDateKey(new Date(a)), kb=localDateKey(new Date(b)); const [ay,am,ad]=ka.split('-').map(Number), [by,bm,bd]=kb.split('-').map(Number); return Math.round((Date.UTC(by,bm-1,bd)-Date.UTC(ay,am-1,ad))/86400000); }
function randomIdPart(){ const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; let s=''; const bytes=new Uint8Array(5); crypto.getRandomValues(bytes); for(const b of bytes)s+=alphabet[b%alphabet.length]; return s; }
async function uniqueUserId(db){ for(let i=0;i<20;i++){const x='CAP'+randomIdPart(); const r=await db.prepare('SELECT 1 FROM users WHERE id=?').bind(x).first(); if(!r)return x;} throw new Error('ID_GENERATION_FAILED'); }
function corsHeaders(origin, env, requestOrigin=''){ const configured=String(env.ALLOWED_ORIGIN||'').trim(); const allowed=configured||requestOrigin; const h={'Access-Control-Allow-Credentials':'true','Access-Control-Allow-Headers':'Content-Type, Idempotency-Key, X-Requested-With','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Vary':'Origin'}; if(origin && allowed && origin===allowed)h['Access-Control-Allow-Origin']=origin; return h; }
function headers(origin,env,requestOrigin=''){ return {'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'strict-origin-when-cross-origin','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'self'; img-src 'self' data: blob: https://assets.coingecko.com https://*.coingecko.com; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self' wss://stream.binance.com https://api.coingecko.com; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",'Strict-Transport-Security':'max-age=31536000; includeSubDomains',...corsHeaders(origin,env,requestOrigin)}; }
function response(data,status=200,origin='',env={},requestOrigin=''){ return new Response(JSON.stringify(data),{status,headers:headers(origin,env,requestOrigin)}); }
function ok(data,origin,env,requestOrigin=''){return response({data},200,origin,env,requestOrigin)}
function fail(code,status=400,origin='',env={},detail,requestOrigin=''){return response({code,...(detail?{detail}: {})},status,origin,env,requestOrigin)}
async function body(req){try{return await req.json()}catch{return {}}}
function cookieMap(req){const o={}; for(const p of (req.headers.get('Cookie')||'').split(';')){const i=p.indexOf('=');if(i>0)o[p.slice(0,i).trim()]=decodeURIComponent(p.slice(i+1).trim())} return o}
function cookie(name,value,maxAge,secure=true){return `${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}${secure?'; Secure':''}`}
async function sha256(value){const b=await crypto.subtle.digest('SHA-256',enc.encode(String(value))); return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function randomToken(){const b=new Uint8Array(32);crypto.getRandomValues(b);return [...b].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function hashPassword(password,saltHex){const salt=saltHex||await randomToken(); const key=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveBits']); const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:hexBytes(salt),iterations:150000,hash:'SHA-256'},key,256); return `pbkdf2$${salt}$${hexBytesToString(bits)}`}
function hexBytes(h){const a=new Uint8Array(h.length/2);for(let i=0;i<a.length;i++)a[i]=parseInt(h.slice(i*2,i*2+2),16);return a}
function hexBytesToString(ab){return [...new Uint8Array(ab)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function verifyPassword(password,stored){const [kind,salt,hash]=String(stored||'').split('$');if(kind!=='pbkdf2'||!salt||!hash)return false; const v=await hashPassword(password,salt); return v===stored}
function safeUser(r){if(!r)return null; const u={...r}; for(const k of Object.keys(u))if(k.endsWith('_micro'))u[k.replace('_micro','')]=money(u[k]); return {id:u.id,name:u.name,family:u.family,email:u.email,status:u.status,createdAt:u.created_at,lastLoginAt:u.last_login_at,wallet:u.wallet,referredBy:u.referred_by,balance:u.balance,available:u.available,investedCapital:u.invested_capital,dailyProfit:u.daily_profit,teamProfit:u.team_profit,referralIncome:u.referral_income,totalProfit:u.total_profit,totalWithdrawals:u.total_withdrawals,activePlan:u.active_plan_vip?{vip:u.active_plan_vip,amount:money(u.active_plan_amount_micro),dailyProfit:money(u.active_plan_daily_profit_micro),activatedAt:u.active_plan_activated_at,status:'active'}:null,profitState:u.profit_state,profitEligibleFromDate:u.profit_eligible_from_date,teamProfitEligibleFromDate:u.team_profit_eligible_from_date,capState:u.cap_status?{status:u.cap_status,capAmount:u.cap_amount_micro==null?null:money(u.cap_amount_micro),capUsed:money(u.cap_used_micro),eligibleAt:u.cap_eligible_at,lastChangedAt:u.cap_last_changed_at}:null,referralBonusAmount:money(u.referral_bonus_amount_micro),referralBonusReversed:Boolean(u.referral_bonus_reversed),pendingWithdrawal:money(u.reserved_withdrawal_micro)} }
async function getUser(db,idv){return db.prepare('SELECT * FROM users WHERE id=?').bind(idv).first()}
async function auth(req,env){const raw=cookieMap(req).capital_session;if(!raw)return null;const h=await sha256(raw);const s=await env.DB.prepare('SELECT * FROM sessions WHERE token_hash=? AND expires_at>?').bind(h,now()).first();if(!s)return null;const ts=now(),ex=new Date(Date.now()+CONFIG.sessionMinutes*60000).toISOString();await env.DB.prepare('UPDATE sessions SET last_active_at=?,expires_at=? WHERE token_hash=?').bind(ts,ex,h).run();const u=await getUser(env.DB,s.user_id);if(!u||u.status!=='active'){await env.DB.prepare('DELETE FROM sessions WHERE token_hash=?').bind(h).run();return null}return u}
async function adminAuth(req,env){const raw=cookieMap(req).capital_admin_session;if(!raw)return null;const h=await sha256(raw);const s=await env.DB.prepare('SELECT * FROM admin_sessions WHERE token_hash=? AND expires_at>?').bind(h,now()).first();if(!s)return null;const ts=now(),ex=new Date(Date.now()+CONFIG.adminSessionMinutes*60000).toISOString();await env.DB.prepare('UPDATE admin_sessions SET last_active_at=?,expires_at=? WHERE token_hash=?').bind(ts,ex,h).run();let account=await env.DB.prepare("SELECT * FROM admin_accounts WHERE email=? AND status='active'").bind(s.email).first();if(!account&&s.email===email(env.ADMIN_EMAIL))account={email:s.email,name:'Owner',role:'owner',permissions_json:'["*"]'};return {...s,account,permissions:JSON.parse(account?.permissions_json||'[]'),last_active_at:ts,expires_at:ex}}
function hasPermission(a,p){return !!a&&(a.account?.role==='owner'||a.permissions.includes('*')||a.permissions.includes(p))}
async function audit(db,admin,action,targetId,meta={}){await db.prepare('INSERT INTO audit_logs(id,admin_email,action,target_id,meta_json,created_at) VALUES(?,?,?,?,?,?)').bind(id('AUD'),admin,action,targetId,json(meta),now()).run()}
async function ledger(db,userId,type,amountMicro,ref,meta={}){await db.prepare('INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(id('LED'),userId,type,amountMicro,ref,json(meta),now()).run()}
function planForAmount(n){const a=Number(n); for(const [vip,p] of Object.entries(PLANS))if(p.amount===a)return Number(vip); return null}
async function directTeamCapital(db,userId){const r=await db.prepare("SELECT COALESCE(SUM(invested_capital_micro),0) AS v FROM users WHERE referred_by=?").bind(userId).first(); return Number(r?.v||0)}
async function capState(db,u){const principal=Number(u.invested_capital_micro||0), team=await directTeamCapital(db,u.id), threshold=principal*CONFIG.teamMultiplier; return {status:principal>0&&team>=threshold?'NO_CAP':'LIMITED_100',teamCapital:team,threshold}}
async function setCapState(db,u,reason='evaluation',evalDate=localDateKey()){
  if(!Number(u.invested_capital_micro))return u;
  const next=await capState(db,u), prev=u.cap_status;
  const ts=now(), nextDate=addLocalDays(evalDate,1), eligible=next.status==='NO_CAP';
  const where="id=? AND ((cap_status=? ) OR (? IS NULL AND cap_status IS NULL))";
  const stmt=db.prepare(`UPDATE users SET cap_status=?,cap_amount_micro=?,cap_used_micro=CASE WHEN cap_status IS NULL OR cap_status<>? THEN 0 ELSE cap_used_micro END,cap_eligible_at=?,cap_last_changed_at=CASE WHEN cap_status<>? OR (cap_status IS NULL AND ? IS NOT NULL) THEN ? ELSE cap_last_changed_at END,profit_state=CASE WHEN cap_status='LIMITED_100' AND ?='NO_CAP' THEN 'pending' ELSE profit_state END,profit_eligible_from_date=CASE WHEN cap_status='LIMITED_100' AND ?='NO_CAP' THEN ? ELSE profit_eligible_from_date END,team_profit_eligible_from_date=CASE WHEN cap_status='LIMITED_100' AND ?='NO_CAP' THEN ? ELSE team_profit_eligible_from_date END,updated_at=? WHERE ${where}`)
    .bind(next.status,next.status==='LIMITED_100'?Number(u.invested_capital_micro):null,next.status,eligible?ts:null,prev,prev,ts,next.status,next.status,nextDate,next.status,nextDate,ts,u.id,prev,prev);
  const result=await db.batch([stmt]);
  const changed=Number(result?.[0]?.meta?.changes||0)===1;
  if(changed&&prev!==next.status){
    await db.prepare('INSERT INTO cap_history(id,user_id,previous_status,new_status,team_capital_micro,threshold_micro,previous_cap_used_micro,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(id('CAP'),u.id,prev,next.status,next.teamCapital,next.threshold,Number(u.cap_used_micro||0),reason,ts).run();
  }
  const fresh=await getUser(db,u.id);
  return {...fresh,teamCapital:next.teamCapital,threshold:next.threshold};
}
async function addIncome(db,u,type,amountMicro,ref,meta={}){
  if(amountMicro<=0)return false;
  const fields={daily_profit_micro:type==='daily_profit'?amountMicro:0,team_profit_micro:type==='team_profit'?amountMicro:0,referral_income_micro:type==='referral_bonus'?amountMicro:0,total_profit_micro:amountMicro,available_micro:amountMicro,balance_micro:amountMicro};
  const lid=id('LED'),ts=now();
  try{
    const result=await db.batch([
      db.prepare('INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(lid,u.id,type,amountMicro,ref,json(meta),ts),
      db.prepare('UPDATE users SET daily_profit_micro=daily_profit_micro+?,team_profit_micro=team_profit_micro+?,referral_income_micro=referral_income_micro+?,total_profit_micro=total_profit_micro+?,available_micro=available_micro+?,balance_micro=balance_micro+?,updated_at=? WHERE id=?').bind(fields.daily_profit_micro,fields.team_profit_micro,fields.referral_income_micro,fields.total_profit_micro,fields.available_micro,fields.balance_micro,ts,u.id)
    ]);
    if(Number(result?.[1]?.meta?.changes||0)!==1)throw Error('USER_UPDATE_FAILED');
    return true;
  }catch(e){if(String(e.message||'').includes('UNIQUE'))return false;throw e;}
}
async function reverseReferral(db,inviter,amountMicro,ref,meta){
  if(amountMicro<=0)return false;
  const fresh=await getUser(db,inviter.id); if(!fresh)return false;
  const available=Math.max(0,Number(fresh.available_micro||0)-amountMicro);
  const balance=Math.max(0,Number(fresh.balance_micro||0)-amountMicro);
  const ts=now(),lid=id('LED');
  try{
    const result=await db.batch([
      db.prepare('INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) VALUES(?,?,?,?,?,?,?)').bind(lid,inviter.id,'referral_reversal',-amountMicro,ref,json(meta),ts),
      db.prepare('UPDATE users SET referral_income_micro=MAX(0,referral_income_micro-?),total_profit_micro=MAX(0,total_profit_micro-?),available_micro=?,balance_micro=?,updated_at=? WHERE id=?').bind(amountMicro,amountMicro,available,balance,ts,inviter.id)
    ]);
    return Number(result?.[1]?.meta?.changes||0)===1;
  }catch(e){if(String(e.message||'').includes('UNIQUE'))return false;throw e;}
}
async function approveDeposit(db,d,admin){
  const u=await getUser(db,d.user_id);
  if(!u)throw Error('USER_NOT_FOUND');
  if(u.status!=='active')throw Error('USER_INACTIVE');
  if(u.active_plan_vip||Number(u.invested_capital_micro)>0)throw Error('PLAN_ACTIVE');
  const vip=planForAmount(money(d.amount_micro));
  if(!vip)throw Error('INVALID_PLAN_AMOUNT');
  const p=PLANS[vip];
  const depositDate=localDateKey(new Date(d.created_at)), approvalDate=localDateKey();
  const beforeCutoff=localMinutes(new Date(d.created_at))<960;
  const first=beforeCutoff&&depositDate===approvalDate?approvalDate:addLocalDays(depositDate,1);
  const sameDay=beforeCutoff&&depositDate===approvalDate;
  const nonce=await randomToken();
  const approvedAt=now();
  const referral= u.referred_by ? await getUser(db,u.referred_by) : null;
  const referralEligible=!!(referral&&referral.status!=='blocked'&&referral.status!=='suspended');
  const referralBonus=referralEligible?Math.round(Number(d.amount_micro)*CONFIG.referralRate):0;
  const referralId=referralBonus?id('RFB'):null;

  const statements=[
    db.prepare("UPDATE deposits SET status='approved',verification_status='verified',blockchain_status='verified',verified_at=?,approved_by=?,processing_nonce=? WHERE id=? AND status='pending'").bind(approvedAt,admin,nonce,d.id),
    db.prepare("UPDATE users SET balance_micro=balance_micro+?,invested_capital_micro=?,active_plan_vip=?,active_plan_amount_micro=?,active_plan_daily_profit_micro=?,active_plan_activated_at=?,profit_state=?,profit_eligible_from_date=?,team_profit_eligible_from_date=?,daily_profit_micro=0,team_profit_micro=0,cap_status=NULL,cap_amount_micro=NULL,cap_used_micro=0,updated_at=? WHERE id=? AND status='active' AND active_plan_vip IS NULL AND invested_capital_micro=0 AND EXISTS (SELECT 1 FROM deposits WHERE id=? AND status='approved' AND processing_nonce=?)").bind(Number(d.amount_micro),Number(d.amount_micro),vip,micro(p.amount),micro(p.daily),approvedAt,sameDay?'active':'pending',first,first,approvedAt,u.id,d.id,nonce),
    db.prepare("INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) SELECT ?,?,?,?,?,?,? WHERE EXISTS (SELECT 1 FROM deposits WHERE id=? AND status='approved' AND processing_nonce=?)").bind(id('LED'),u.id,'deposit',Number(d.amount_micro),d.id,json({network:d.network,txid:d.txid,originalInvestment:true,vip}),approvedAt,d.id,nonce)
  ];
  if(sameDay){
    statements.push(
      db.prepare("UPDATE users SET daily_profit_micro=daily_profit_micro+?,total_profit_micro=total_profit_micro+?,available_micro=available_micro+?,balance_micro=balance_micro+?,updated_at=? WHERE id=? AND EXISTS (SELECT 1 FROM deposits WHERE id=? AND processing_nonce=?)").bind(micro(p.daily),micro(p.daily),micro(p.daily),micro(p.daily),approvedAt,u.id,d.id,nonce),
      db.prepare("INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) SELECT ?,?,?,?,?,?,? WHERE EXISTS (SELECT 1 FROM deposits WHERE id=? AND processing_nonce=?)").bind(id('LED'),u.id,'daily_profit',micro(p.daily),`${approvalDate}:daily`,json({profitDate:approvalDate,vip,principal:Number(d.amount_micro),sameDayDeposit:true}),approvedAt,d.id,nonce)
    );
  }
  if(referralBonus){
    statements.push(
      db.prepare("UPDATE users SET referral_income_micro=referral_income_micro+?,total_profit_micro=total_profit_micro+?,available_micro=available_micro+?,balance_micro=balance_micro+?,updated_at=? WHERE id=? AND status NOT IN ('blocked','suspended') AND EXISTS (SELECT 1 FROM deposits WHERE id=? AND processing_nonce=?)").bind(referralBonus,referralBonus,referralBonus,referralBonus,approvedAt,referral.id,d.id,nonce),
      db.prepare("UPDATE users SET referral_bonus_id=?,referral_bonus_amount_micro=?,referral_bonus_recipient=? WHERE id=? AND EXISTS (SELECT 1 FROM deposits WHERE id=? AND processing_nonce=?)").bind(referralId,referralBonus,u.id,u.id,d.id,nonce),
      db.prepare("INSERT INTO ledger_entries(id,user_id,type,amount_micro,reference_id,meta_json,created_at) SELECT ?,?,?,?,?,?,? WHERE EXISTS (SELECT 1 FROM users WHERE id=? AND referral_bonus_id=? ) AND EXISTS (SELECT 1 FROM deposits WHERE id=? AND processing_nonce=?)").bind(id('LED'),referral.id,'referral_bonus',referralBonus,d.id,json({rate:CONFIG.referralRate,inviteeId:u.id,investment:Number(d.amount_micro)}),approvedAt,referral.id,referralId,d.id,nonce),
      db.prepare('UPDATE deposits SET referral_bonus_id=?,referral_bonus_amount_micro=?,referral_bonus_recipient=? WHERE id=? AND processing_nonce=?').bind(referralId,referralBonus,referral.id,d.id,nonce)
    );
  }
  const result=await db.batch(statements);
  const claim=result[0];
  if(!claim?.meta||Number(claim.meta.changes||0)!==1)throw Error('ALREADY_PROCESSED');
  const fresh=await getUser(db,u.id);
  await setCapState(db,fresh,'deposit-approved');
  await audit(db,admin,'deposit.approve',d.id,{userId:u.id,amount:money(d.amount_micro),vip,firstProfitDay:first});
}
async function processDailyDate(db,dateKey){
  const pending=(await db.prepare("SELECT * FROM withdrawals WHERE status='pending'").all()).results;
  for(const w of pending){if(localDateKey(new Date(w.created_at))<dateKey){await db.batch([db.prepare("UPDATE withdrawals SET status='expired',processed_at=? WHERE id=? AND status='pending'").bind(now(),w.id),db.prepare("UPDATE users SET reserved_withdrawal_micro=MAX(0,reserved_withdrawal_micro-?),updated_at=? WHERE id=?").bind(Number(w.amount_micro),now(),w.user_id)]);await audit(db,'SYSTEM','withdraw.expire',w.id,{reason:'pending crossed Afghanistan financial day'})}}
  const users=(await db.prepare("SELECT * FROM users WHERE status IN ('active','suspended','blocked') AND invested_capital_micro>0").all()).results;
  for(let u of users){
    u=await getUser(db,u.id);await setCapState(db,u,'daily-evaluation',dateKey);u=await getUser(db,u.id);if(u.status!=='active')continue;
    if(u.profit_state==='pending'&&u.profit_eligible_from_date&&dateKey>=u.profit_eligible_from_date){await db.prepare("UPDATE users SET profit_state='active',updated_at=? WHERE id=?").bind(now(),u.id).run();u=await getUser(db,u.id)}
    if(u.cap_status==='LIMITED_100'&&Number(u.cap_used_micro)>=Number(u.cap_amount_micro||0)){await db.prepare("UPDATE users SET profit_state='stopped',updated_at=? WHERE id=?").bind(now(),u.id);continue}
    if(u.profit_state!=='active')continue;
    const vip=Number(u.active_plan_vip),plan=PLANS[vip];if(!plan)continue;
    await addIncome(db,u,'daily_profit',micro(plan.daily),`${dateKey}:daily`,{profitDate:dateKey,vip,principal:Number(u.invested_capital_micro)});
    const children=(await db.prepare("SELECT * FROM users WHERE referred_by=? AND status='active' AND invested_capital_micro>0").bind(u.id).all()).results;
    for(const child of children){const start=child.team_profit_eligible_from_date||child.profit_eligible_from_date||dateKey;if(dateKey<start)continue;const v=Math.round(Number(child.invested_capital_micro)*CONFIG.teamRate);if(v<=0)continue;await addIncome(db,u,'team_profit',v,`${dateKey}:team:${child.id}`,{profitDate:dateKey,memberId:child.id,memberInvestment:Number(child.invested_capital_micro),rate:CONFIG.teamRate});}
  }
}
async function ensureDaily(db){
  const today=localDateKey();const meta=await db.prepare("SELECT value FROM system_meta WHERE key='last_daily_run'").first();
  let start=meta?.value?addLocalDays(meta.value,1):today;
  let cursor=start,processed=0;
  while(cursor<=today&&processed<7){await processDailyDate(db,cursor);await db.prepare("INSERT OR REPLACE INTO system_meta(key,value) VALUES('last_daily_run',?)").bind(cursor).run();cursor=addLocalDays(cursor,1);processed++;}
  await db.prepare("DELETE FROM auth_attempts WHERE created_at<?").bind(new Date(Date.now()-24*60*60*1000).toISOString()).run();
  await db.prepare("DELETE FROM reset_tokens WHERE expires_at<=?").bind(now()).run();
}
async function notifications(db,u){const reads=new Set((await db.prepare('SELECT notification_id FROM notification_reads WHERE user_id=?').bind(u.id).all()).results.map(x=>x.notification_id));const ws=(await db.prepare("SELECT * FROM withdrawals WHERE user_id=? AND status IN ('completed','rejected','expired') ORDER BY created_at DESC").bind(u.id).all()).results.map(w=>({id:'withdrawal:'+w.id,kind:'withdrawal',status:w.status,title:w.status==='rejected'?'Withdrawal rejected':'Withdrawal processed',body:w.status==='rejected'?(w.reject_reason||'Your withdrawal was rejected.'):`Withdrawal ${money(w.amount_micro).toFixed(2)} USDT was processed.`,createdAt:w.processed_at||w.created_at,read:reads.has('withdrawal:'+w.id)}));const an=(await db.prepare("SELECT * FROM announcements WHERE user_id IS NULL OR user_id=? ORDER BY created_at DESC").bind(u.id).all()).results.map(a=>({id:'announcement:'+a.id,kind:'admin',status:'info',title:a.title,body:a.body,createdAt:a.created_at,read:reads.has('announcement:'+a.id)}));return [...ws,...an].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))}
function validWallet(v){return /^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(String(v||'').trim())}
function validEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email(v))}
function validPassword(v){const p=String(v||'');return p.length>=8&&p.length<=128}
function validLoginPassword(v){const p=String(v||'');return p.length>=6&&p.length<=128}
function requestIp(req){return String(req.headers.get('CF-Connecting-IP')||req.headers.get('X-Forwarded-For')||'unknown').split(',')[0].trim().slice(0,128)}
async function rateLimit(db,key,max,windowMs){const cutoff=new Date(Date.now()-windowMs).toISOString();const r=await db.prepare('SELECT COUNT(*) c FROM auth_attempts WHERE key=? AND created_at>?').bind(key,cutoff).first();if(Number(r?.c||0)>=max)return false;await db.prepare('INSERT INTO auth_attempts(key,created_at) VALUES(?,?)').bind(key,now()).run();return true}
function secureCookie(req,name,value,maxAge){return cookie(name,value,maxAge,new URL(req.url).protocol==='https:')}
function requestOriginAllowed(req,env){const origin=req.headers.get('Origin');if(!origin)return true;const allowed=String(env.ALLOWED_ORIGIN||new URL(req.url).origin).trim();return origin===allowed}
async function requireSafeRequest(req,env,origin){if(!['POST','PUT','PATCH','DELETE'].includes(req.method))return true;if(!origin)return true;return requestOriginAllowed(req,env)}
function idemKey(req,bodyValue){const raw=String(req.headers.get('Idempotency-Key')||bodyValue||'').trim();return raw.slice(0,128)}

async function settingsMap(db){const rows=(await db.prepare('SELECT key,value FROM system_settings').all()).results;return Object.fromEntries(rows.map(r=>[r.key,r.value]));}
async function publicConfig(db,env){const st=await settingsMap(db);return {timezone:TZ,plans:Object.fromEntries(Object.entries(PLANS).map(([vip,p])=>[vip,{amount:p.amount,daily:p.daily}])),deposit:{network:st.deposit_network||CONFIG.depositNetwork,currency:st.deposit_currency||CONFIG.depositCurrency,address:String(env.DEPOSIT_ADDRESS||CONFIG.depositAddress),minAmount:100},withdrawal:{network:st.withdrawal_network||CONFIG.withdrawalNetwork,currency:st.withdrawal_currency||CONFIG.withdrawalCurrency,minByVip:{1:10,2:20,3:30,4:40,5:50},window:{start:Number(st.withdrawal_window_start||CONFIG.withdrawalWindowStart),end:Number(st.withdrawal_window_end||CONFIG.withdrawalWindowEnd)}}};}
async function dashboard(db,u){const c=await setCapState(db,u,'dashboard');const fresh=await getUser(db,u.id);const pending=Number(fresh.reserved_withdrawal_micro||0);return {...safeUser(fresh),pendingWithdrawal:money(pending),withdrawableAvailable:Math.max(0,money(fresh.available_micro-pending)),capStatus:c.status,capAmount:c.status==='LIMITED_100'?money(fresh.invested_capital_micro):null,capUsed:money(fresh.cap_used_micro),teamCapital:money(c.teamCapital),teamThreshold:money(c.threshold)} }
async function userTeam(db,u){const direct=(await db.prepare("SELECT COUNT(*) c,COALESCE(SUM(invested_capital_micro),0) v FROM users WHERE referred_by=? AND status='active'").bind(u.id).first());const seen=new Set(),q=(await db.prepare("SELECT id FROM users WHERE referred_by=? AND status!='blocked' AND status!='suspended'").bind(u.id).all()).results.map(x=>x.id);while(q.length){const x=q.shift();if(seen.has(x))continue;seen.add(x);const kids=(await db.prepare("SELECT id FROM users WHERE referred_by=? AND status!='blocked' AND status!='suspended'").bind(x).all()).results;for(const k of kids)q.push(k.id)}return {directMembers:Number(direct.c||0),teamMembers:seen.size,directTeamCapital:money(direct.v)} }
async function adminLists(db,path){ if(path==='/users'){const rows=(await db.prepare("SELECT * FROM users ORDER BY created_at DESC").all()).results;const out=[];for(const u of rows)if(u.status!=='deleted'){const c=await capState(db,u);out.push({...safeUser(u),directTeamCapital:money(c.teamCapital),capStatus:c.status})}return out} if(path==='/deposits'){return (await db.prepare('SELECT d.*,u.name,u.family,u.email FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.created_at DESC').all()).results.map(x=>({...x,amount:money(x.amount_micro)}))} if(path==='/withdrawals'){return (await db.prepare('SELECT w.*,u.name,u.family,u.email FROM withdrawals w JOIN users u ON u.id=w.user_id ORDER BY w.created_at DESC').all()).results.map(x=>({...x,amount:money(x.amount_micro),fee:money(x.fee_micro),netAmount:money(x.net_amount_micro)}))} if(path==='/transactions'){return (await db.prepare('SELECT * FROM ledger_entries ORDER BY created_at DESC LIMIT 500').all()).results.map(x=>({...x,amount:money(x.amount_micro),meta:JSON.parse(x.meta_json||'{}')}))} if(path==='/activity'){return (await db.prepare('SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT 500').all()).results.map(x=>({...x,admin:x.admin_email,targetId:x.target_id,meta:JSON.parse(x.meta_json||'{}')}))} return [] }
