export default { async fetch(req,env,ctx){const url=new URL(req.url);if(url.pathname.startsWith('/api/'))return api(req,env);if(req.method==='GET'&&url.pathname==='/')return env.ASSETS.fetch(new Request(new URL('/frontend/index.html',req.url),req));if(req.method==='GET'&&url.pathname==='/admin')return env.ASSETS.fetch(new Request(new URL('/admin/login.html',req.url),req));return env.ASSETS.fetch(req)}, async scheduled(event,env,ctx){ctx.waitUntil(ensureDaily(env.DB))} };
